@dataclass(frozen=True)
class Order:
    id: OrderId
    customer: CustomerId
    lines: tuple[Line, ...]

    def __post_init__(self) -> None:
        if not self.lines:
            raise DomainRule("cannot open an empty order")

    @classmethod
    def from_cart(cls, customer: CustomerId, cart: Sequence[CartItem]) -> "Order":
        return cls(id=OrderId.new(), customer=customer, lines=tuple(map(compile_line, cart)))
